import requests
import json

# Function to search for flights using the Amadeus API
def search_flights(origin, destination, departure_date, arrival_date, airline_filter=None):
    # Example API key for Amadeus
    amadeus_access_key = 'your_access_key_here'
    amadeus_access_secret = 'your_access_secret_here'

    headers = {
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {amadeus_access_key}'
    }

    payload = {
        'request': {
            'origin': origin,
            'destination': destination,
            'departure_date': departure_date,
            'arrival_date': arrival_date
        }
    }

    # Making the request to Amadeus API
    response = requests.post('https://us1.amadeus.com/v2/shopping/flight-search', headers=headers, json=payload)

    if response.status_code == 200:
        return response.json()
    else:
        return {'error': f'Failed to get flight search results. Status code: {response.status_code}'}

# Example usage
origin = 'New York (JFK)'
destination = 'London (LHR)'
departure_date = '2023-12-01'
arrival_date = '2023-12-05'

flights_data = search_flights(origin, destination, departure_date, arrival_date)
print(f"Flight Search Results: {json.dumps(flights_data, indent=2)}")
